    s.textContent = `
.l32 { display: grid; gap: 12px; min-width: 0; }
.l32 .l32-row { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.l32 .l32-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 12px; align-items: start; }
@media (max-width: 720px) { .l32 .l32-grid { grid-template-columns: minmax(0, 1fr); } }
.l32 .l32-st { display: grid; grid-template-columns: 1.6rem minmax(0, 1fr) auto; gap: 2px 8px; align-items: center; border: 1.5px solid var(--line); border-radius: 10px; padding: 6px 9px; background: var(--surface); transition: border-color .25s, background .25s, opacity .25s; }
.l32 .l32-st .n { font-family: var(--mono); font-size: .78rem; color: var(--muted); text-align: center; }
.l32 .l32-st b { font-size: .86rem; display: block; }
.l32 .l32-st small { color: var(--muted); font-size: .74rem; }
.l32 .l32-st .t { font-family: var(--mono); font-size: .76rem; direction: ltr; white-space: nowrap; padding: 1px 7px; border-radius: 999px; background: var(--code-bg); }
.l32 .l32-st.on { border-color: var(--accent); background: var(--accent-soft); }
.l32 .l32-st.todo { opacity: .45; }
.l32 .l32-st.skip { opacity: .35; text-decoration: line-through; }
.l32 .l32-pipe { display: grid; gap: 5px; align-content: start; }
.l32 pre.l32-json { white-space: pre-wrap; overflow-wrap: anywhere; direction: ltr; text-align: left; background: var(--code-bg); border-radius: 8px; padding: 10px; margin: 0; font-size: .74rem; line-height: 1.55; font-family: var(--mono); min-height: 12em; }
.l32 pre.l32-json .k { color: var(--muted); }
.l32 pre.l32-json .new { background: var(--accent-soft); border-radius: 3px; }
.l32 .he { direction: rtl; unicode-bidi: plaintext; }
.l32 .l32-panel { border-inline-start: 3px solid var(--signal); background: var(--signal-soft); border-radius: 0 10px 10px 0; padding: 10px 14px; line-height: 1.7; min-height: 5.5em; }
.l32 .l32-panel p { margin: 0 0 6px; } .l32 .l32-panel p:last-child { margin: 0; }
.l32 .l32-tl { position: relative; display: grid; gap: 4px; direction: ltr; }
.l32 .l32-tl .lane { display: grid; grid-template-columns: 3.2rem minmax(0, 1fr); gap: 6px; align-items: center; font-size: .74rem; }
.l32 .l32-tl .lane > span:first-child { color: var(--muted); font-family: var(--mono); }
.l32 .l32-tl .track { position: relative; height: 16px; background: var(--code-bg); border-radius: 4px; overflow: hidden; }
.l32 .l32-tl .bar { position: absolute; top: 0; bottom: 0; border-radius: 4px; opacity: .9; transition: width .4s; }
.l32 .l32-tl .bar.stt { background: var(--signal); } .l32 .l32-tl .bar.llm { background: var(--accent); } .l32 .l32-tl .bar.tts { background: var(--good); }
.l32 .l32-tl .mark { position: absolute; top: -2px; bottom: -2px; width: 2px; background: var(--bad); }
.l32 .l32-tl .axis { display: flex; justify-content: space-between; font-family: var(--mono); font-size: .7rem; color: var(--muted); padding-inline-start: 3.6rem; }
.l32 .chips { display: flex; flex-wrap: wrap; gap: 4px; }
.l32 .chip2 { font-size: .78rem; border: 1px solid var(--line); border-radius: 999px; padding: 1px 8px; background: var(--surface); }
.l32 .w-ok, .l32 .w-homophone { color: var(--good); font-weight: 600; } .l32 .w-close { color: var(--signal); font-weight: 600; } .l32 .w-wrong, .l32 .w-missing { color: var(--bad); font-weight: 600; text-decoration: underline; }
.l32 .l32-map { width: 100%; max-width: 520px; height: auto; display: block; border-radius: 12px; border: 1px solid var(--line); background: var(--surface); }
.l32 .l32-map .pin { cursor: pointer; }
.l32 .l32-map .pin circle { fill: var(--surface); stroke: var(--muted); stroke-width: 2; }
.l32 .l32-map .pin.sel circle { fill: var(--accent-soft); stroke: var(--accent); stroke-width: 3; }
.l32 .l32-map text { font-size: 13px; fill: var(--ink); }
.l32 .l32-card { border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; background: var(--surface); display: grid; gap: 6px; min-width: 0; }
.l32 .l32-card h5 { margin: 0; font-size: .86rem; color: var(--muted); font-weight: 600; }
.l32 .l32-card ul { margin: 0; padding-inline-start: 18px; line-height: 1.7; }
.l32 .ar { direction: rtl; font-size: .88rem; color: var(--muted); }
.l32 .l32-voc { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1fr); gap: 2px 10px; font-size: .84rem; }
.l32 .l32-voc span { overflow-wrap: anywhere; }
.l32 .l32-voc .hd { color: var(--muted); font-size: .74rem; }
.l32 pre.l32-block { white-space: pre-wrap; overflow-wrap: anywhere; direction: ltr; text-align: left; background: var(--code-bg); border-radius: 8px; padding: 8px 10px; margin: 0; font-size: .72rem; line-height: 1.5; font-family: var(--mono); }
.l32 .l32-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 8px; }
.l32 .l32-stat { border: 1px solid var(--line); border-radius: 10px; padding: 8px 10px; background: var(--surface); }
.l32 .l32-stat b { font-size: 1.25rem; font-family: var(--mono); display: block; direction: ltr; text-align: right; }
.l32 .l32-stat small { color: var(--muted); font-size: .74rem; display: block; }
.l32 .l32-ci { position: relative; height: 8px; background: var(--code-bg); border-radius: 4px; margin-top: 6px; direction: ltr; }
.l32 .l32-ci i { position: absolute; top: 0; bottom: 0; background: var(--accent); opacity: .45; border-radius: 4px; }
.l32 .l32-ci u { position: absolute; top: -3px; bottom: -3px; width: 3px; background: var(--accent); }
.l32 .l32-list { display: grid; gap: 4px; max-height: 360px; overflow-y: auto; }
.l32 .l32-item { display: grid; grid-template-columns: 2.6rem minmax(0, 1fr) auto; gap: 6px; align-items: center; border: 1px solid var(--line); border-radius: 8px; padding: 5px 8px; background: var(--surface); cursor: pointer; text-align: right; font: inherit; color: inherit; width: 100%; }
.l32 .l32-item[aria-pressed="true"] { border-color: var(--accent); background: var(--accent-soft); }
.l32 .l32-item .id { font-family: var(--mono); font-size: .74rem; color: var(--muted); direction: ltr; }
.l32 .l32-item .tx { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: .86rem; }
.l32 .pill { font-size: .72rem; padding: 1px 7px; border-radius: 999px; white-space: nowrap; border: 1px solid var(--line); }
.l32 .pill.hit { background: var(--good-soft); border-color: var(--good); } .l32 .pill.miss { background: var(--bad-soft); border-color: var(--bad); }
.l32 .pill.fp { background: var(--signal-soft); border-color: var(--signal); } .l32 .pill.ok { background: var(--code-bg); }
.l32 .l32-kv { display: grid; grid-template-columns: minmax(0, 7.5rem) minmax(0, 1fr); gap: 3px 10px; font-size: .84rem; }
.l32 .l32-kv > span:nth-child(odd) { color: var(--muted); }
.l32 select { font: inherit; padding: 4px 6px; border-radius: 8px; border: 1px solid var(--line); background: var(--surface); color: var(--ink); max-width: 100%; }
`;
    document.head.appendChild(s);
