  const ciBar = (c) => c.n ? `<div class="l32-ci" title="Wilson 95%"><i style="left:${c.low * 100}%;width:${(c.high - c.low) * 100}%"></i><u style="left:calc(${c.value * 100}% - 1px)"></u></div>` : "";
